import java.util.ArrayList;
import java.util.List;

class Solution {
    public int[] largestPower(int[] nums) {
            int[] power = new int[15];
                    List<List<Integer>> groups = new ArrayList<>();
                            
                                    List<Integer> initialGroup = new ArrayList<>();
                                            for (int num : nums) {
                                                        initialGroup.add(num);
                                                                }
                                                                        groups.add(initialGroup);

                                                                                for (int i = 0; i < 15; i++) {
                                                                                            int bit = 14 - i;
                                                                                                        int count = 0;
                                                                                                                    List<List<Integer>> nextGroups = new ArrayList<>();
                                                                                                                                boolean splitDone = false;

                                                                                                                                            for (List<Integer> group : groups) {
                                                                                                                                                            if (splitDone) {
                                                                                                                                                                                nextGroups.add(group);
                                                                                                                                                                                                    continue;
                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    List<Integer> withBit = new ArrayList<>();
                                                                                                                                                                                                                                                    List<Integer> withoutBit = new ArrayList<>();

                                                                                                                                                                                                                                                                    for (int num : group) {
                                                                                                                                                                                                                                                                                        if (((num >> bit) & 1) == 1) {
                                                                                                                                                                                                                                                                                                                withBit.add(num);
                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                            withoutBit.add(num);
                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                if (withoutBit.isEmpty()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                    // All elements in this group have the bit set
                                                                                                                                                                                                                                                                                                                                                                                                                                                        count += withBit.size();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            nextGroups.add(group);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // First group containing elements without the bit set: split and stop
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    count += withBit.size();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!withBit.isEmpty()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                nextGroups.add(withBit);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        nextGroups.add(withoutBit);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            splitDone = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    power[i] = count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                groups = nextGroups;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return power;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }